import EventEmitter from "events";
import * as fs from "fs";

export class Options {
  flush: boolean;
  lock: boolean;
  TTL: number;
  constructor(lock: boolean = false, TTL: number = 0, flush: boolean = true) {
    this.lock = lock;
    this.flush = flush;
    this.TTL = TTL;
  }
}

export class Data<T> {
  val: T;
  timestamp: number;
  lock: boolean;
  TTL: number;
  constructor(val: T, lock: boolean = false, TTL: number = 0) {
    this.val = val;
    this.timestamp = Date.now();
    this.lock = lock;
    this.TTL = TTL;
  }
}

export class DataSet<T> {
  [key: string]: Data<T>;
}

export class ErrorVal {
  type: "Error" = "Error";
  message: string;
  constructor(
    message: string = "",
  ) {
    this.message = message;
  }
}

export class Database<T> extends EventEmitter {
  #name: string;
  #filePath: string;
  #fullPath: string;
  #data: DataSet<T> = new DataSet<T>();
  #fileLock: boolean = false;
  #permanence: boolean = true;

  constructor(
    name: string,
    path: string = "./database/",
    perm: boolean = true,
  ) {
    super();
    this.#name = name;
    this.#filePath = path;
    this.#fullPath = this.#filePath + this.#name + ".json";
    this.#permanence = perm;
    if (fs.existsSync(this.#fullPath) && this.#permanence) {
      try {
        this.#data = JSON.parse(fs.readFileSync(this.#fullPath).toString());
        this.#checkTTL().then(() => {});
      } catch {
        fs.writeFileSync(this.#fullPath, "{}");
      }
    }
  }

  async flush():Promise<undefined | ErrorVal>{
      if (!this.#permanence) {
        return undefined;
      }
      if (this.#fileLock) {
        return new ErrorVal("File locked!");
      }
      this.#fileLock = true;
      fs.writeFile(
        this.#fullPath,
        JSON.stringify(this.#data),
        "utf8",
        (err) => {
          if (err) return new ErrorVal(err.message);
          this.#fileLock = false;
          this.emit("flush");
          return undefined;
        },
      );
  }

  async #checkTTL():Promise<undefined | ErrorVal> {
      for (let key in this.#data) {
        if (
          this.#data[key].TTL > 0 &&
          this.#data[key].timestamp + this.#data[key].TTL <= Date.now()
        ) {
         await this.Delete(key);
        }
      }
      return undefined;
  }

  Exists(key: string): boolean {
    return this.#data[key] !== undefined;
  }

  async Set(
    key: string,
    val: any,
    options: Options = new Options(),
  ): Promise<boolean >{
      if (!this.Exists(key)) {
        this.#data[key] = new Data(val, options.lock, options.TTL);
        await this.#checkTTL()
        await this.flush()
        this.emit("set", key, this.#data[key]);
        return true;
      } else if (this.#data[key].lock === false) {
        this.#data[key] = new Data(val, options.lock, options.TTL);
        this.emit("set", key, this.#data[key]);
        return true;
      }
    return false;
  }

  async Get(key: string):Promise<T| undefined> {
      await this.#checkTTL();
        if (this.Exists(key)) {
          this.emit("get", key, this.#data[key].val);
          return this.#data[key].val;
    }
    return undefined;
  }

  async Take(key: string): Promise<T | undefined> {
        await this.#checkTTL();
        if (this.Exists(key)) {
          let temp: Data<T> = this.#data[key];
          await this.Delete(key);
          this.emit("take", key, temp.val);
          return temp.val;
        }
    return undefined;

  }

  async Lock(key: string): Promise<boolean> {
      if (!this.Exists(key)) {
        return false;
      } else if (this.#data[key].TTL <= 0) {
        return false;
      }
      this.#data[key].lock = true;
      this.emit("lock", key, this.#data[key]);
      return true;
  }

  async Delete(key: string): Promise<boolean> {
      if (!this.Exists(key)) {
        return false;
      }
      this.emit("delete", key);
      delete this.#data[key];
      return true;
  }
  async Close(): Promise<boolean> {
      await this.flush();
      this.#data = {};
      this.emit("close");
      return true;
  }
}
